def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    at_field_start = True
    i = 0
    n = len(line)

    while i < n:
        ch = line[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field))
                field = []
                at_field_start = True
            elif ch == '"' and at_field_start:
                in_quotes = True
                at_field_start = False
            else:
                field.append(ch)
                at_field_start = False

        i += 1

    fields.append(''.join(field))
    return fields
